// ── WEATHER ───────────────────────────────────────────────────
// WMO weather interpretation codes → {label, emoji}
// Covers the full WMO code set used by Open-Meteo
function wmoCondition(code) {
  if(code===0)                        return {label:"Clear",      emoji:"☀️"};
  if(code===1)                        return {label:"Mostly clear",emoji:"🌤️"};
  if(code===2)                        return {label:"Partly cloudy",emoji:"⛅"};
  if(code===3)                        return {label:"Overcast",   emoji:"☁️"};
  if(code>=45&&code<=48)              return {label:"Fog",        emoji:"🌫️"};
  if(code>=51&&code<=55)              return {label:"Drizzle",    emoji:"🌦️"};
  if(code>=56&&code<=57)              return {label:"Freezing drizzle",emoji:"🌧️"};
  if(code>=61&&code<=65)              return {label:"Rain",       emoji:"🌧️"};
  if(code>=66&&code<=67)              return {label:"Freezing rain",emoji:"🌨️"};
  if(code>=71&&code<=77)              return {label:"Snow",       emoji:"❄️"};
  if(code>=80&&code<=82)              return {label:"Showers",    emoji:"🌦️"};
  if(code===85||code===86)            return {label:"Snow showers",emoji:"🌨️"};
  if(code>=95&&code<=99)              return {label:"Thunderstorm",emoji:"⛈️"};
  return {label:"Unknown", emoji:"🌡️"};
}
function WeatherBadge({weather}) {
  // weather = {temp, condition: {label, emoji}} | null
  if(!weather) return null;
  return (
    <span style={{
      display:"inline-flex", alignItems:"center", gap:5,
      background:"rgba(74,144,184,0.12)", border:"1.5px solid rgba(74,144,184,0.35)",
      borderRadius:20, padding:"4px 12px", fontSize:18, fontWeight:600,
      color:sky, fontFamily:FONT, whiteSpace:"nowrap"
    }}>
      {weather.condition.emoji} {Math.round(weather.temp)}°F · {weather.condition.label}
    </span>
  );
}

